  "implementation": "import math

def solve(case):
    # Validate required fields
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    for key in ('sentence_vectors', 'query_vector', 'context_weight'):
        if key not in case:
            raise ValueError(f"Missing required field: {key}")
    sentence_vectors = case['sentence_vectors']
    query_vector = case['query_vector']
    context_weight = case['context_weight']
    if not isinstance(sentence_vectors, list) or not isinstance(query_vector, list):
        raise ValueError("sentence_vectors and query_vector must be lists")
    if not isinstance(context_weight, (int, float)):
        raise ValueError("context_weight must be a number")
    n = len(sentence_vectors)
    if n == 0:
        return {"ranking": [], "scores": []}
    # Validate vector dimensions
    query_len = len(query_vector)
    if query_len == 0:
        raise ValueError("query_vector cannot be empty")
    for i, sv in enumerate(sentence_vectors):
        if not isinstance(sv, list):
            raise ValueError(f"sentence_vectors[{i}] is not a list")
        if len(sv) != query_len:
            raise ValueError(f"sentence_vectors[{i}] length differs from query_vector")
        for val in sv:
            if not isinstance(val, (int, float)):
                raise ValueError(f"sentence_vectors[{i}] contains non-numeric value")
    for val in query_vector:
        if not isinstance(val, (int, float)):
            raise ValueError("query_vector contains non-numeric value")

    # Compute cosine similarities
    def dot(a, b):
        return sum(x*y for x,y in zip(a,b))
    def norm(v):
        return math.sqrt(dot(v, v))
    similarities = []
    for sv in sentence_vectors:
        norm_sv = norm(sv)
        norm_q = norm(query_vector)
        if norm_sv == 0 or norm_q == 0:
            sim = 0.0
        else:
            sim = dot(sv, query_vector) / (norm_sv * norm_q)
        similarities.append(sim)

    # Compute neighbor averages and blend
    scores = []
    for i in range(n):
        own_sim = similarities[i]
        neighbors = []
        if i > 0:
            neighbors.append(similarities[i-1])
        if i < n-1:
            neighbors.append(similarities[i+1])
        if neighbors:
            neighbor_avg = sum(neighbors) / len(neighbors)
        else:
            neighbor_avg = 0.0
        score = (1 - context_weight) * own_sim + context_weight * neighbor_avg
        # Round to 10 decimal places for deterministic output
        scores.append(round(score, 10))

    # Build ranking: descending score, then ascending index for ties
    indices = list(range(n))
    indices.sort(key=lambda i: (-scores[i], i))
    ranking = indices

    return {"ranking": ranking, "scores": scores}
